const m = $input.first().json.message || {};
return [{ json: {
  chatId: m.chat?.id,
  text: m.text || m.caption || '',
  voiceFileId: m.voice?.file_id || m.audio?.file_id || null,
  msgDate: m.date || Math.floor(Date.now()/1000)
} }];

const b = $('Normalize input').item.json;
const t = $input.first().json.text || '';
return [{ json: { ...b, text: t, isVoice: true } }];

const b = $('Normalize input').item.json;
const msgDate = new Date(b.msgDate * 1000);
const ufa = new Date(msgDate.getTime() + 5 * 60 * 60 * 1000);

const day = ufa.getUTCDate();
const month = ufa.getUTCMonth();
const year = ufa.getUTCFullYear();
const hours = String(ufa.getUTCHours()).padStart(2, '0');
const minutes = String(ufa.getUTCMinutes()).padStart(2, '0');

const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];
const weekdays = ['воскресенье','понедельник','вторник','среда','четверг','пятница','суббота'];

return [{
  json: {
    todayISO: year + '-' + String(month + 1).padStart(2, '0') + '-' + String(day).padStart(2, '0'),
    todayHuman: day + ' ' + months[month] + ' ' + year,
    todayWeekday: weekdays[ufa.getUTCDay()],
    todayTime: hours + ':' + minutes,
    currentYear: year
  }
}];

const rows = $input.all().map(x => x.json);
const msg = $('Prepare voice').isExecuted ? $('Prepare voice').first().json : $('Prepare text').first().json;
const d = $('Current Date Info').first().json;
const todayISO = d.todayISO;

const active = rows.filter(r => {
  const status = String(r.status || '').toLowerCase().trim();
  const date = String(r.date || '').trim();
  return status === 'active' && date >= todayISO;
});

const sorted = active.sort((a, b) => {
  const da = (a.date || '') + ' ' + (a.time || '');
  const db = (b.date || '') + ' ' + (b.time || '');
  return da.localeCompare(db);
});

const allActive = sorted.map(r => ({
  id: String(r.id).trim(),
  clientName: r.clientName,
  phone: r.phone || '',
  date: r.date,
  time: r.time,
  status: r.status
}));

return [{
  json: {
    chatId: msg.chatId,
    text: msg.text,
    todayISO: d.todayISO,
    todayHuman: d.todayHuman,
    todayWeekday: d.todayWeekday,
    todayTime: d.todayTime,
    currentYear: d.currentYear,
    bookings: allActive.slice(0, 30),
    allBookings: allActive
  }
}];

const raw = String($input.first().json.output || '').replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/,'').trim();
const c = $('Build context').first().json;

let parsed;
try { parsed = JSON.parse(raw); } catch(e) {
  parsed = { actions: [], reply: 'Ой, я запуталась 🌸 Повтори, пожалуйста.' };
}

let actions = [];
if (Array.isArray(parsed.actions)) actions = parsed.actions;
else if (parsed.action) actions = [parsed];

const ALLOWED = ['create','update','cancel','list'];
actions = actions
  .filter(a => a && ALLOWED.includes(a.action))
  .map(a => ({
    action: a.action,
    id: String(a.id || '').trim(),
    clientName: String(a.clientName || '').trim(),
    phone: String(a.phone || '').trim(),
    date: String(a.date || '').trim(),
    time: String(a.time || '').trim(),
    status: a.status || (a.action === 'cancel' ? 'cancelled' : 'active'),
    filter: String(a.filter || '').trim(),
    type: String(a.type || 'busy').trim()
  }));

if (!parsed.reply) parsed.reply = actions.length > 0 ? 'Готово 🌸' : 'Не поняла 🌸';

return [{ json: { ...c, actions, reply: parsed.reply } }];

const input = $input.first().json;
const actions = input.actions;
return actions.map((a, idx) => ({
  json: {
    ...a,
    chatId: input.chatId,
    allBookings: input.allBookings || [],
    __reply: input.reply,
    __idx: idx,
    __total: actions.length
  }
}));

const items = $input.all();
const result = [];
for (const item of items) {
  const x = item.json;
  if (!x.clientName || !x.date || !x.time) continue;

  const dateClean = String(x.date).replace(/-/g, '');
  const timeClean = String(x.time).replace(/:/g, '');
  const suffix = Math.random().toString(36).slice(2, 6);
  const uuid = 'EVE-' + dateClean + '-' + timeClean + '-' + suffix;

  const b = $('Normalize input').item.json;
  const now = new Date(b.msgDate * 1000).toISOString();

  result.push({
    json: {
      id: uuid, clientName: x.clientName, phone: String(x.phone || ''), date: x.date, time: x.time, status: 'active',
      createdAt: now, updatedAt: now, __idx: x.__idx, __total: x.__total, __reply: x.__reply, __action: 'create', chatId: x.chatId
    }
  });
}
return result;

const items = $input.all();
return items.map(item => ({
  json: { __idx: item.json.__idx, __total: item.json.__total, __reply: item.json.__reply, __action: 'create', chatId: item.json.chatId, __done: true }
}));

const items = $input.all();
const result = [];
const contextBookings = $('Build context').first().json.allBookings || [];
const b = $('Normalize input').first().json;
const now = new Date(b.msgDate * 1000).toISOString();

for (const item of items) {
  const x = item.json;
  if (!x.id) continue;

  let booking = contextBookings.find(bk => String(bk.id).trim() === String(x.id).trim());
  if (!booking && x.clientName) {
    const cleanName = String(x.clientName).toLowerCase().trim();
    const cleanDate = x.date || '';
    booking = contextBookings.find(bk => {
      const nameMatch = String(bk.clientName || '').toLowerCase().trim() === cleanName;
      const dateMatch = !cleanDate || String(bk.date) === String(cleanDate);
      return nameMatch && dateMatch;
    });
  }
  if (!booking) continue;

  result.push({
    json: {
      id: String(booking.id).trim(), clientName: booking.clientName, phone: x.phone || booking.phone || '', date: x.date || booking.date, time: x.time || booking.time,
      status: x.action === 'cancel' ? 'cancelled' : (x.status || 'active'), updatedAt: now,
      __idx: x.__idx, __total: x.__total, __reply: x.__reply, __action: x.action, chatId: x.chatId
    }
  });
}
return result;

const items = $input.all();
return items.map(item => ({
  json: { __idx: item.json.__idx, __total: item.json.__total, __reply: item.json.__reply, __action: item.json.__action || 'update', chatId: item.json.chatId, __done: true }
}));

// Собираем ВСЕ даты из всех действий
const allActions = $input.all();
let allDates = [];
let listType = 'busy';

for (const action of allActions) {
  const filter = String(action.json.filter || '');
  listType = action.json.type || 'busy';

  if (filter.includes(',')) {
    allDates.push(...filter.split(',').map(d => d.trim()));
  } else {
    allDates.push(filter);
  }
}

// Убираем дубликаты дат
allDates = [...new Set(allDates)];

// Если в фильтре 'all' или 'week', обрабатываем как обычно
const today = $('Current Date Info').first().json.todayISO;
const allBookings = $('Build context').first().json.allBookings || [];
const bookings = allBookings.filter(b => String(b.date || '').trim() >= today);

const schedule = {
  0: [], 1: ["09:00", "10:30", "12:00", "13:30"], 2: ["09:00", "10:30", "12:00", "13:30"], 3: ["09:00", "10:30", "12:00", "13:30"], 4: [], 5: ["09:00", "10:30", "12:00", "13:30"], 6: ["12:00", "13:30", "15:00"]
};
const months = ['января','февраля','марта','апреля','мая','июня','июля','августа','сентября','октября','ноября','декабря'];

let reply = '';

// Функция для обработки одной даты
function processDate(date, type) {
  const [y, m, d] = date.split('-');
  if (!y || !m || !d) return '';

  const dayOfWeek = new Date(date + 'T00:00:00Z').getUTCDay();
  const workSlots = schedule[dayOfWeek] || [];
  const dayBookings = bookings.filter(b => String(b.date).trim() === date);

  if (workSlots.length === 0) {
    return `📅 ${parseInt(d)} ${months[parseInt(m)-1]} — выходной 💅\n\n`;
  }

  if (type === 'busy') {
    if (dayBookings.length === 0) {
      return `📅 ${parseInt(d)} ${months[parseInt(m)-1]} — весь день свободен 🌸\n\n`;
    } else {
      let res = `📅 ${parseInt(d)} ${months[parseInt(m)-1]} ${y}:\n`;
      const sorted = dayBookings.sort((a, b) => (a.time || '').localeCompare(b.time || ''));
      for (const b of sorted) {
        const phoneStr = b.phone ? ` (${b.phone})` : '';
        res += `⏰ ${b.time} — ${b.clientName}${phoneStr}\n`;
      }
      return res + '\n';
    }
  } else if (type === 'free') {
    const busyTimes = dayBookings.map(b => {
      let t = String(b.time).trim();
      if (t.length === 4) t = '0' + t; 
      return t;
    });
    const freeSlots = workSlots.filter(slot => !busyTimes.includes(slot));
    if (freeSlots.length === 0) {
      return `📅 ${parseInt(d)} ${months[parseInt(m)-1]} — всё занято 🈚\n\n`;
    } else {
      return `📅 ${parseInt(d)} ${months[parseInt(m)-1]} ${y}:\n🟢 Свободно: ${freeSlots.join(', ')}\n\n`;
    }
  }
  return '';
}

if (allDates.length > 0 && allDates[0] !== 'all' && allDates[0] !== 'week') {
  // Обрабатываем конкретные даты
  for (const date of allDates) {
    reply += processDate(date, listType);
  }
} else {
  // Обработка 'all' или 'week' (упрощенная версия)
  if (allDates[0] === 'week') {
    for (let i = 0; i < 7; i++) {
      const d = new Date(today + 'T00:00:00Z');
      d.setUTCDate(d.getUTCDate() + i);
      reply += processDate(d.toISOString().split('T')[0], listType);
    }
  } else if (allDates[0] === 'all') {
    if (bookings.length === 0) {
      reply = 'У тебя пока нет активных записей 💅';
    } else {
      const byDate = {};
      for (const b of bookings) {
        const dateKey = String(b.date).trim();
        if (!byDate[dateKey]) byDate[dateKey] = [];
        byDate[dateKey].push(b);
      }
      for (const date of Object.keys(byDate).sort()) {
        reply += processDate(date, 'busy');
      }
    }
  }
}

// Проверяем, что запрос действительно содержит несколько дат, и мы не обрабатывали 'all' или 'week'
if (!reply.trim()) reply = 'На эти даты записей нет 💅';

// Возвращаем ОДИН ответ, чтобы не дублировать сообщения
return [{ json: { chatId: $('Build context').first().json.chatId, reply: reply.trim() } }];

// Берем данные напрямую из нужных узлов
const contextData = $('Build context').first().json;
const parseData = $('Parse command').first().json;

// Нам нужно просто найти правильный текст ответа
let reply = parseData.reply || 'Готово 🌸';

// Проверяем, не сгенерировал ли текст узел списков или обновлений
// (используем try/catch на случай, если ветка не выполнялась)
try {
  const formatList = $('Format list reply').first().json;
  if (formatList && formatList.reply) reply = formatList.reply;
} catch(e) {}

try {
  const updateDone = $('Update done').first().json;
  if (updateDone && updateDone.__reply) reply = updateDone.__reply;
} catch(e) {}

// ⚠️ МАГИЯ: Мы не используем $input.all(). 
// Мы жестко возвращаем ровно ОДИН элемент.
return [
  {
    json: { 
      chatId: contextData.chatId, 
      reply: reply 
    } 
  }
];
